mapper.select:
        SELECT * FROM store
        
            
                AND (sname LIKE '%' || #{keyword} || '%' OR scategory LIKE '%' || #{keyword} || '%')
            

            
                AND 
                
                    scategory LIKE '%' || #{item} || '%'
                
            

            
                AND 
                
                    skeyword LIKE '%' || #{item} || '%'
                
            

            
                AND ssido = #{ssido}
            

            
                AND sparking = #{sparking}
            

            
                AND sstatus = #{sstatus}
            
        
        ORDER BY sno ASC
